<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use DateTime;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\LongTask\Runner;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskKey;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Revoke\UserPersonalApiKeyRevokeUsecase;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\Gateway\UserPersonalApiKeyFilter;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driver\Batch\UserPersonalApiKeyTaskRevoke;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Revoke\UserPersonalApiKeyRevokeResult;

class UserPersonalApiKeyRevokeController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly Runner $runner,
        private readonly SqlTemplate $sql,
        private readonly UserPersonalApiKeyRevokeUsecase $revokeUsecase,
    ) {
    }
    #[OA\Patch(
        path: "/api/access/me/api-keys/{uid}/revoke",
        tags: ["User personal api key"],
        description: "Update the value",
        parameters: [
        new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
        responses: [
        new OA\Response(response: 200, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/UserPersonalApiKeyApiDTO")),
        new OA\Response(response: 404, description: "Not found"),
    ]
    )
    ]
    public function revoke(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("revoke for User personal api key");
        $span = $this->startSpan("revoke for User personal api key");
        $this->sql->begin();
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $result = $this->revokeUsecase->revoke($uid);
            $this->sql->commit();
            $value = $this->mapUserPersonalApiKey($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(201)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }
    public function revokeAllForQuery(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("revoke all for query User personal api key");
        $span = $this->startSpan("revoke all for query User personal api key");
        try {
            $params = $request->getQueryParams();
            $filter = new UserPersonalApiKeyFilter(
                uids: isset($params['uid']) ? [$params['uid']] : (isset($params['uids']) ? explode(',', $params['uids']) : null),
                search: $params['search'] ?? null,
                keyHash: $params['key-hash'] ?? null,
                user: isset($params['user']) ? new UserRef($params['user']) : null,
                name: $params['name'] ?? null,
            );
            $res = $this->runner->run(UserPersonalApiKeyTaskRevoke::class, ['filter' => $filter]);
            $encoded = json_encode($res);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function checkRevokeAllForQueryStatus(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Check revoke all for query User personal api key");
        $span = $this->startSpan("Check revoke all for query User personal api key");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $info = $this->runner->detail(new TaskKey($uid));
            if (!$info) {
                throw new NotFoundException('-');
            }
            $encoded = json_encode($info);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapUserPersonalApiKey(ServerRequestInterface $request, UserPersonalApiKeyRevokeResult $value): UserPersonalApiKeyApiDTO
    {
        $this->logDebug("Map entity to output dto for User personal api key");
        $span = $this->startSpan("Map entity to output dto for User personal api key");
        try {
            $user = $value->getUser();
            $dto = new UserPersonalApiKeyApiDTO();
            $dto->uid = $value->getUid();
            $dto->user = $user ? ['$ref' => $user->uid()] : null;
            $dto->name = $value->getName();
            $dto->keyHash = $value->getKeyHash();
            $dto->scopes = $value->getScopes();
            $dto->lastUsedAt = $value->getLastUsedAt()?->format(DateTime::ATOM);
            $dto->expiresAt = $value->getExpiresAt()?->format(DateTime::ATOM);
            $dto->createdAt = $value->getCreatedAt()?->format(DateTime::ATOM);
            $dto->enabled = $value->isEnabled();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
